  const githubOutput = process.env.GITHUB_OUTPUT;
  if (githubOutput) appendFileSync(githubOutput, `session_type=${sessionType}\nsession_number=${sessionNumber}\n`);

  console.error(`Fetched ${events.length} events → ${values.out}`);
}

